package com.groupeventnotifications;

enum EventCategory
{
	DROP("GROUP DROP"),
	LEVEL_UP("LEVEL UP"),
	QUEST("QUEST COMPLETED"),
	DIARY("ACHIEVEMENT DIARY"),
	COMBAT_ACHIEVEMENT("COMBAT ACHIEVEMENT"),
	COLLECTION_LOG("COLLECTION LOG");

	private final String title;

	EventCategory(String title)
	{
		this.title = title;
	}

	String getTitle()
	{
		return title;
	}
}

package com.groupeventnotifications;

import java.awt.image.BufferedImage;
import java.time.Instant;

final class GroupEvent
{
	private final EventCategory category;
	private final String player;
	private final String detail;
	private final String source;
	private final int itemId;
	private final int quantity;
	private final int value;
	private Instant startsAt;
	private Instant expiresAt;
	private BufferedImage image;

	GroupEvent(EventCategory category, String player, String detail, String source, int itemId,
		int quantity, int value, Instant expiresAt)
	{
		this.category = category;
		this.player = player;
		this.detail = detail;
		this.source = source;
		this.itemId = itemId;
		this.quantity = quantity;
		this.value = value;
		this.startsAt = Instant.now();
		this.expiresAt = expiresAt;
	}

	EventCategory getCategory() { return category; }
	String getPlayer() { return player; }
	String getDetail() { return detail; }
	String getSource() { return source; }
	int getItemId() { return itemId; }
	int getQuantity() { return quantity; }
	int getValue() { return value; }
	Instant getStartsAt() { return startsAt; }
	void setStartsAt(Instant startsAt) { this.startsAt = startsAt; }
	Instant getExpiresAt() { return expiresAt; }
	void setExpiresAt(Instant expiresAt) { this.expiresAt = expiresAt; }
	BufferedImage getImage() { return image; }
	void setImage(BufferedImage image) { this.image = image; }
}

package com.groupeventnotifications;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(GroupEventNotificationsConfig.GROUP)
public interface GroupEventNotificationsConfig extends Config
{
	String GROUP = "groupEventNotifications";

	@ConfigItem(keyName = "minimumDropValue", name = "Minimum drop value",
		description = "Only show drops worth at least this much. Unpriced always-list items are still shown.", position = 0)
	@Units("gp")
	@Range(min = 0)
	default int minimumDropValue() { return 1_000_000; }

	@ConfigItem(keyName = "alwaysNotifyItems", name = "Always notify items",
		description = "Comma-separated item names, matched without regard to capitalisation", position = 1)
	default String alwaysNotifyItems() { return ""; }

	@ConfigItem(keyName = "ignoredItems", name = "Ignored items",
		description = "Comma-separated item names that never create a drop notification", position = 2)
	default String ignoredItems() { return ""; }

	@ConfigItem(keyName = "showDrops", name = "Drops", description = "Show drop notifications", position = 3)
	default boolean showDrops() { return true; }

	@ConfigItem(keyName = "showLevelUps", name = "Level ups", description = "Show level-up notifications", position = 4)
	default boolean showLevelUps() { return true; }

	@ConfigItem(keyName = "showQuests", name = "Quests", description = "Show quest notifications", position = 5)
	default boolean showQuests() { return true; }

	@ConfigItem(keyName = "showDiaries", name = "Achievement diaries", description = "Show diary notifications", position = 6)
	default boolean showDiaries() { return true; }

	@ConfigItem(keyName = "showCombatAchievements", name = "Combat achievements",
		description = "Show combat achievement notifications", position = 7)
	default boolean showCombatAchievements() { return true; }

	@ConfigItem(keyName = "showCollectionLog", name = "Collection log",
		description = "Show collection log notifications", position = 8)
	default boolean showCollectionLog() { return true; }

	@ConfigItem(keyName = "durationSeconds", name = "Duration",
		description = "How long each notification remains visible", position = 9)
	@Units(Units.SECONDS)
	@Range(min = 2, max = 20)
	default int durationSeconds() { return 6; }

	@ConfigItem(keyName = "playSound", name = "Sound", description = "Play a short system sound", position = 10)
	default boolean playSound() { return true; }

	@ConfigItem(keyName = "debugMode", name = "Debug mode",
		description = "Log chat message type, sender and plain text locally to RuneLite logs", position = 11)
	default boolean debugMode() { return false; }

}

package com.groupeventnotifications;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.TextComponent;

final class GroupEventNotificationsOverlay extends Overlay
{
	private static final int MIN_WIDTH = 210;
	private static final int MAX_WIDTH = 300;
	private static final int BASE_HEIGHT = 92;
	private static final int SOURCE_HEIGHT = 108;
	private static final int PADDING = 14;
	private static final int ICON_SIZE = 36;
	private static final int ICON_GAP = 8;
	private static final long ANIMATION_MILLIS = 350;
	private final GroupEventNotificationsPlugin plugin;

	@Inject
	GroupEventNotificationsOverlay(GroupEventNotificationsPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GroupEvent event = plugin.peekEvent();
		Instant now = Instant.now();
		if (event == null || event.getExpiresAt().isBefore(now))
		{
			plugin.removeExpiredEvent();
			return null;
		}
		if (event.getStartsAt().isAfter(now))
		{
			return null;
		}

		long elapsed = Duration.between(event.getStartsAt(), now).toMillis();
		long remaining = Duration.between(now, event.getExpiresAt()).toMillis();
		double enterProgress = clamp(elapsed / (double) ANIMATION_MILLIS);
		double exitProgress = clamp(remaining / (double) ANIMATION_MILLIS);
		double visibility = Math.min(easeOutCubic(enterProgress), easeOutCubic(exitProgress));
		boolean hasSource = !event.getSource().isEmpty();
		int height = hasSource ? SOURCE_HEIGHT : BASE_HEIGHT;
		int slideOffset = (int) Math.round(-height * (1.0 - visibility));

		String title = event.getCategory().getTitle();
		String player = event.getPlayer();
		String detail = shorten(event.getDetail(), 34);
		String source = event.getSource().isEmpty() ? "" : shorten("From " + event.getSource(), 34);
		String value = event.getValue() > 0 ? String.format("%,d gp", event.getValue()) : "";
		Font titleFont = graphics.getFont().deriveFont(Font.BOLD, 11f);
		Font playerFont = graphics.getFont().deriveFont(Font.BOLD, 13f);
		Font detailFont = graphics.getFont().deriveFont(Font.PLAIN, 12f);
		Font valueFont = graphics.getFont().deriveFont(Font.BOLD, 11f);
		int textWidth = Math.max(textWidth(graphics, source, detailFont), Math.max(
			Math.max(textWidth(graphics, title, titleFont), textWidth(graphics, player, playerFont)),
			Math.max(textWidth(graphics, detail, detailFont), textWidth(graphics, value, valueFont))));
		int iconClearance = event.getImage() == null ? PADDING * 2 : (PADDING + ICON_SIZE + ICON_GAP) * 2;
		int width = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, textWidth + iconClearance));
		int textCenterX = width / 2;

		AffineTransform originalTransform = graphics.getTransform();
		graphics.translate(0, slideOffset);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Color accent = accent(event.getCategory());
		drawOsrsFrame(graphics, width, height, accent);

		if (event.getImage() != null)
		{
			graphics.drawImage(event.getImage(), PADDING, (height - ICON_SIZE) / 2, ICON_SIZE, ICON_SIZE, null);
		}
		drawCenteredText(graphics, title, textCenterX, 22, accent, titleFont);
		drawCenteredText(graphics, player, textCenterX, 42, Color.WHITE, playerFont);
		drawCenteredText(graphics, detail, textCenterX, 61, new Color(224, 219, 207), detailFont);
		if (hasSource)
		{
			drawCenteredText(graphics, source, textCenterX, 79,
				new Color(170, 165, 153), detailFont);
		}
		if (event.getValue() > 0)
		{
			drawCenteredText(graphics, value, textCenterX, hasSource ? 98 : 80,
				new Color(255, 205, 54), valueFont);
		}
		graphics.setTransform(originalTransform);
		return new Dimension(width, height);
	}

	private void drawOsrsFrame(Graphics2D graphics, int width, int height, Color accent)
	{
		graphics.setColor(new Color(8, 8, 8, 245));
		graphics.fillRect(0, 0, width, height);
		graphics.setColor(new Color(71, 69, 63));
		graphics.drawRect(1, 1, width - 3, height - 3);
		graphics.setColor(new Color(30, 30, 30, 245));
		graphics.fillRect(5, 5, width - 10, height - 10);
		graphics.setColor(new Color(62, 61, 57));
		graphics.drawLine(5, 5, width - 6, 5);
		graphics.drawLine(5, 5, 5, height - 6);
		graphics.setColor(new Color(12, 12, 12));
		graphics.drawLine(5, height - 6, width - 6, height - 6);
		graphics.drawLine(width - 6, 5, width - 6, height - 6);
		graphics.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), 170));
		graphics.fillRect(7, 7, width - 14, 2);
	}

	private double clamp(double value)
	{
		return Math.max(0.0, Math.min(1.0, value));
	}

	private double easeOutCubic(double value)
	{
		return 1.0 - Math.pow(1.0 - value, 3.0);
	}

	private int textWidth(Graphics2D graphics, String text, Font font)
	{
		return text.isEmpty() ? 0 : graphics.getFontMetrics(font).stringWidth(text);
	}

	private void drawCenteredText(Graphics2D graphics, String text, int centerX, int y, Color color, Font font)
	{
		TextComponent component = new TextComponent();
		component.setPosition(new java.awt.Point(centerX - textWidth(graphics, text, font) / 2, y));
		component.setText(text);
		component.setColor(color);
		component.setFont(font);
		component.render(graphics);
	}

	private Color accent(EventCategory category)
	{
		switch (category)
		{
			case DROP: return new Color(178, 102, 255);
			case LEVEL_UP: return new Color(38, 198, 218);
			case QUEST: return new Color(83, 214, 120);
			case DIARY: return new Color(255, 193, 7);
			case COMBAT_ACHIEVEMENT: return new Color(239, 83, 80);
			default: return new Color(66, 165, 245);
		}
	}

	private String shorten(String value, int maximum)
	{
		return value.length() <= maximum ? value : value.substring(0, maximum - 3) + "...";
	}
}

package com.groupeventnotifications;

import com.google.inject.Provides;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.SoundEffectID;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(name = "GIM Notifications", description = "Prominent Group Ironman event notifications", tags = {"group", "ironman", "gim", "drop"})
public class GroupEventNotificationsPlugin extends Plugin
{
	private static final int MAX_QUEUE_SIZE = 10;
	private final Deque<GroupEvent> events = new ArrayDeque<>();
	private final GroupEventParser parser = new GroupEventParser();

	@Inject private GroupEventNotificationsConfig config;
	@Inject private Client client;
	@Inject private GroupEventNotificationsOverlay overlay;
	@Inject private OverlayManager overlayManager;
	@Inject private ItemManager itemManager;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		events.clear();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.CLAN_GIM_MESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage()).trim();
		if (config.debugMode())
		{
			log.info("GEN chat: type={}, name='{}', message='{}'", event.getType(),
				Text.removeTags(event.getName()), message);
		}

		parser.parse(message).filter(this::categoryEnabled).ifPresent(this::handle);
	}

	private void handle(ParsedGroupEvent parsed)
	{
		if (parsed.getCategory() != EventCategory.DROP)
		{
			enqueue(new GroupEvent(parsed.getCategory(), parsed.getPlayer(), parsed.getDetail(), parsed.getSource(),
				-1, 1, 0, expiry()));
			return;
		}

		String normalizedName = normalize(parsed.getItemName());
		if (csv(config.ignoredItems()).contains(normalizedName)) return;
		boolean always = csv(config.alwaysNotifyItems()).contains(normalizedName);
		Optional<ItemPrice> match = itemManager.search(parsed.getItemName()).stream()
			.filter(item -> normalize(item.getName()).equals(normalizedName)).findFirst();
		int itemId = "coins".equals(normalizedName) ? ItemID.COINS_995 : match.map(ItemPrice::getId).orElse(-1);
		int marketPrice = match.map(ItemPrice::getPrice).orElse(0);
		int value = calculateDropValue(normalizedName, marketPrice, parsed.getQuantity());
		if (!always && value < config.minimumDropValue()) return;

		GroupEvent notification = new GroupEvent(EventCategory.DROP, parsed.getPlayer(), parsed.getDetail(), parsed.getSource(),
			itemId, parsed.getQuantity(), value, expiry());
		if (itemId >= 0) notification.setImage(itemManager.getImage(itemId, parsed.getQuantity(), false));
		enqueue(notification);
	}

	private void enqueue(GroupEvent event)
	{
		removeExpiredEvent();
		while (events.size() >= MAX_QUEUE_SIZE) events.removeLast();
		Instant now = Instant.now();
		Instant displayAfter = events.isEmpty() || events.peekLast().getExpiresAt().isBefore(now)
			? now : events.peekLast().getExpiresAt();
		event.setStartsAt(displayAfter);
		event.setExpiresAt(displayAfter.plusSeconds(config.durationSeconds()));
		events.addLast(event);
		if (config.playSound())
		{
			client.playSoundEffect(SoundEffectID.GE_ADD_OFFER_DINGALING);
		}
	}

	GroupEvent peekEvent() { return events.peekFirst(); }
	void removeExpiredEvent()
	{
		while (!events.isEmpty() && events.peekFirst().getExpiresAt().isBefore(Instant.now())) events.removeFirst();
	}

	private Instant expiry() { return Instant.now().plusSeconds(config.durationSeconds()); }
	static int calculateDropValue(String normalizedName, int marketPrice, int quantity)
	{
		int unitPrice = "coins".equals(normalizedName) ? 1 : Math.max(0, marketPrice);
		return (int) Math.min(Integer.MAX_VALUE, (long) unitPrice * Math.max(1, quantity));
	}

	private boolean categoryEnabled(ParsedGroupEvent event)
	{
		switch (event.getCategory())
		{
			case DROP: return config.showDrops();
			case LEVEL_UP: return config.showLevelUps();
			case QUEST: return config.showQuests();
			case DIARY: return config.showDiaries();
			case COMBAT_ACHIEVEMENT: return config.showCombatAchievements();
			case COLLECTION_LOG: return config.showCollectionLog();
			default: return false;
		}
	}

	private Set<String> csv(String value)
	{
		return Arrays.stream(value.split(",")).map(this::normalize).filter(s -> !s.isEmpty()).collect(Collectors.toSet());
	}
	private String normalize(String value) { return value.trim().toLowerCase(Locale.ENGLISH); }

	@Provides
	GroupEventNotificationsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroupEventNotificationsConfig.class);
	}
}

package com.groupeventnotifications;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * All message-format assumptions live here. Add real messages captured by debug
 * mode as test cases before widening a pattern.
 */
final class GroupEventParser
{
	private static final String PLAYER = "(?<player>[^:]+?)";
	private static final Pattern DROP = Pattern.compile("^" + PLAYER
		+ "(?: has)? (?:received|obtained|got) (?:(?<quantity>[0-9,]+) x )?(?<item>.+?)(?: from (?<source>.+?))?[.!]?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern GIM_DROP = Pattern.compile("^" + PLAYER
		+ " received a drop: (?:(?<quantity>[0-9,]+) x )?(?<item>.+?)"
		+ "(?: \\([0-9,]+ coins?\\))?(?: from (?<source>.+?))?[.!]?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern LEVEL_UP = Pattern.compile("^" + PLAYER
		+ "(?: has)? (?:reached|achieved) (?:level )?(?<level>[0-9]{1,4}) (?:in|for) (?<skill>[A-Za-z ]+?)[.!]?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern LEVEL_UP_REVERSED = Pattern.compile("^" + PLAYER
		+ "(?: has)? (?:reached|achieved) (?<skill>[A-Za-z ]+?) level (?<level>[0-9]{1,4})[.!]?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern QUEST = Pattern.compile("^" + PLAYER
		+ "(?: has)? completed (?:the quest )?(?<detail>.+?)[.!]?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern DIARY = Pattern.compile("^" + PLAYER
		+ "(?: has)? completed (?:(?:an?|the) )?(?:achievement diary|diary)(?:: | - )?(?<detail>.+?)[.!]?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern COMBAT = Pattern.compile("^" + PLAYER
		+ "(?: has)? completed (?:(?:the|a) )?combat achievement(?:: | - )?(?<detail>.+?)[.!]?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern COLLECTION = Pattern.compile("^" + PLAYER
		+ "(?: has)? added (?<detail>.+?) to (?:their|the) collection log[.!]?$", Pattern.CASE_INSENSITIVE);

	Optional<ParsedGroupEvent> parse(String message)
	{
		Matcher matcher = COMBAT.matcher(message);
		if (matcher.matches()) return achievement(matcher, EventCategory.COMBAT_ACHIEVEMENT);
		matcher = DIARY.matcher(message);
		if (matcher.matches()) return achievement(matcher, EventCategory.DIARY);
		matcher = QUEST.matcher(message);
		if (matcher.matches()) return achievement(matcher, EventCategory.QUEST);
		matcher = COLLECTION.matcher(message);
		if (matcher.matches()) return achievement(matcher, EventCategory.COLLECTION_LOG);
		matcher = LEVEL_UP.matcher(message);
		if (matcher.matches()) return levelUp(matcher);
		matcher = LEVEL_UP_REVERSED.matcher(message);
		if (matcher.matches()) return levelUp(matcher);
		matcher = GIM_DROP.matcher(message);
		if (matcher.matches()) return drop(matcher);
		matcher = DROP.matcher(message);
		if (!matcher.matches()) return Optional.empty();
		return drop(matcher);
	}

	private Optional<ParsedGroupEvent> drop(Matcher matcher)
	{
		String quantity = matcher.group("quantity");
		int amount = quantity == null ? 1 : parseQuantity(quantity);
		String item = clean(matcher.group("item"));
		String source = clean(matcher.group("source"));
		String detail = amount > 1 ? String.format("%,d x %s", amount, item) : item;
		return Optional.of(new ParsedGroupEvent(EventCategory.DROP,
			clean(matcher.group("player")), detail, item, source, amount));
	}

	private Optional<ParsedGroupEvent> levelUp(Matcher matcher)
	{
		String detail = clean(matcher.group("skill")) + " level " + matcher.group("level");
		return Optional.of(new ParsedGroupEvent(EventCategory.LEVEL_UP,
			clean(matcher.group("player")), detail, null, "", 1));
	}

	private Optional<ParsedGroupEvent> achievement(Matcher matcher, EventCategory category)
	{
		return Optional.of(new ParsedGroupEvent(category, clean(matcher.group("player")),
			clean(matcher.group("detail")), null, "", 1));
	}

	private int parseQuantity(String value)
	{
		try { return Math.max(1, Integer.parseInt(value.replace(",", ""))); }
		catch (NumberFormatException ignored) { return 1; }
	}

	private String clean(String value)
	{
		return value == null ? "" : value.trim().replaceAll("[.!]+$", "");
	}
}

package com.groupeventnotifications;

final class ParsedGroupEvent
{
	private final EventCategory category;
	private final String player;
	private final String detail;
	private final String itemName;
	private final String source;
	private final int quantity;

	ParsedGroupEvent(EventCategory category, String player, String detail, String itemName, String source, int quantity)
	{
		this.category = category;
		this.player = player;
		this.detail = detail;
		this.itemName = itemName;
		this.source = source;
		this.quantity = quantity;
	}

	EventCategory getCategory() { return category; }
	String getPlayer() { return player; }
	String getDetail() { return detail; }
	String getItemName() { return itemName; }
	String getSource() { return source; }
	int getQuantity() { return quantity; }
}

