package com.groupeventnotifications;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GroupEventParserTest
{
	private final GroupEventParser parser = new GroupEventParser();

	@Test
	public void parsesDrop()
	{
		ParsedGroupEvent event = parser.parse("Brother received 2 x Bandos chestplate from General Graardor.").orElseThrow(AssertionError::new);
		assertEquals(EventCategory.DROP, event.getCategory());
		assertEquals("Brother", event.getPlayer());
		assertEquals("Bandos chestplate", event.getItemName());
		assertEquals(2, event.getQuantity());
	}

	@Test
	public void parsesRealGimDropWithoutSource()
	{
		ParsedGroupEvent event = parser.parse("Iron Timzor received a drop: Bones (31 coins).").orElseThrow(AssertionError::new);
		assertEquals(EventCategory.DROP, event.getCategory());
		assertEquals("Iron Timzor", event.getPlayer());
		assertEquals("Bones", event.getItemName());
		assertEquals(1, event.getQuantity());
	}

	@Test
	public void parsesRealGimStackedDropWithSource()
	{
		ParsedGroupEvent event = parser.parse("Iron Timzor received a drop: 30 x Cosmic rune (3,540 coins) from Sergeant Strongstack.").orElseThrow(AssertionError::new);
		assertEquals(EventCategory.DROP, event.getCategory());
		assertEquals("Cosmic rune", event.getItemName());
		assertEquals(30, event.getQuantity());
		assertEquals("30 x Cosmic rune", event.getDetail());
		assertEquals("Sergeant Strongstack", event.getSource());
	}

	@Test
	public void parsesCombatAchievementBeforeGenericQuest()
	{
		ParsedGroupEvent event = parser.parse("Brother completed the combat achievement: Perfect Olm.").orElseThrow(AssertionError::new);
		assertEquals(EventCategory.COMBAT_ACHIEVEMENT, event.getCategory());
	}

	@Test
	public void ignoresOrdinaryChat()
	{
		assertTrue(!parser.parse("Hello everyone").isPresent());
	}

	@Test
	public void parsesLevelUp()
	{
		ParsedGroupEvent event = parser.parse("Brother has reached level 75 in Slayer.").orElseThrow(AssertionError::new);
		assertEquals(EventCategory.LEVEL_UP, event.getCategory());
		assertEquals("Slayer level 75", event.getDetail());
	}

	@Test
	public void parsesReversedLevelUp()
	{
		ParsedGroupEvent event = parser.parse("Brother achieved Fishing level 99!").orElseThrow(AssertionError::new);
		assertEquals(EventCategory.LEVEL_UP, event.getCategory());
		assertEquals("Fishing level 99", event.getDetail());
	}
